    return {"x_header": x_header}

client = TestClient(app)

def test_underscore_header_not_accepted():
    # CLAIM 1: When convert_underscores=True (default), headers with underscores should not be accepted
    # If I send "x_header", it should NOT be matched to the parameter "x_header"
    response = client.get("/", headers={"x_header": "value"})
    # If it is NOT accepted, it will either be missing (if optional) or result in a 422 (if required)
    # In this case x_header is required (str, no default). So 422 is expected.
    assert response.status_code == 422, f"Should have failed with 422 for underscore header, but got {response.status_code} and {response.json()}"

