    @app.get("/underscore")
    async def read_underscore(x_header: str = Header(convert_underscores=False)):
        return {"x_header": x_header}

    response = client.get("/underscore", headers={"x_header": "value"})
    assert response.status_code == 200
    assert response.json() == {"x_header": "value"}
